/**
 * @file speciesBaseStats.ts
 * Raw species base stats (POKEMON_BASE_STATS) for tooltips and storage sorting.
 */

import { POKEMON_BASE_STATS, type PokemonBaseStat } from '../../pokemonStats.ts';
import { resolveRosterSpeciesKey } from './wildEncounterSpecies.ts';
import type { CreatureData } from '../types/creature.js';

export type SpeciesRawStatBlock = {
  hp: number;
  attack: number;
  spattack: number;
  defense: number;
  spdefense: number;
  speed: number;
};

export type SpeciesBaseStatScale = {
  minima: SpeciesRawStatBlock;
  maxima: SpeciesRawStatBlock;
  totalMin: number;
  totalMax: number;
};

export type BaseStatTooltipLabels = {
  stat: string;
  value: string;
  total: string;
  rows: ReadonlyArray<{ key: keyof SpeciesRawStatBlock; label: string }>;
};

const STAT_KEYS: ReadonlyArray<keyof SpeciesRawStatBlock> = [
  'hp',
  'attack',
  'spattack',
  'defense',
  'spdefense',
  'speed',
];

const FALLBACK_STATS: SpeciesRawStatBlock = {
  hp: 1,
  attack: 1,
  spattack: 1,
  defense: 1,
  spdefense: 1,
  speed: 1,
};

/** HP is stored at full official scale in POKEMON_BASE_STATS; other stats are halved. */
export const HP_BASE_STAT_GAUGE_WEIGHT = 0.5;

let cachedScale: SpeciesBaseStatScale | null = null;

/** Stat value for gauge bars / weighted BST (HP counts half). */
export function getWeightedSpeciesRawStat(
  key: keyof SpeciesRawStatBlock,
  value: number,
): number {
  return key === 'hp' ? value * HP_BASE_STAT_GAUGE_WEIGHT : value;
}

export function getWeightedSpeciesRawBaseStats(block: SpeciesRawStatBlock): SpeciesRawStatBlock {
  return {
    hp: getWeightedSpeciesRawStat('hp', block.hp),
    attack: block.attack,
    spattack: block.spattack,
    defense: block.defense,
    spdefense: block.spdefense,
    speed: block.speed,
  };
}

/** Weighted BST for gauges and base-stat total sort (HP counts half, floored). */
export function sumWeightedSpeciesRawBaseStats(block: SpeciesRawStatBlock): number {
  return Math.floor(
    block.hp * HP_BASE_STAT_GAUGE_WEIGHT
      + block.attack
      + block.spattack
      + block.defense
      + block.spdefense
      + block.speed,
  );
}

function toStatBlock(raw: PokemonBaseStat): SpeciesRawStatBlock {
  return {
    hp: Number(raw.hp) || 0,
    attack: Number(raw.attack) || 0,
    spattack: Number(raw.spattack ?? raw.attack) || 0,
    defense: Number(raw.defense) || 0,
    spdefense: Number(raw.spdefense ?? raw.defense) || 0,
    speed: Number(raw.speed) || 0,
  };
}

/** Raw POKEMON_BASE_STATS entry (no level, IV, or other modifiers). */
export function getSpeciesRawBaseStats(speciesName: string): SpeciesRawStatBlock {
  const key = resolveRosterSpeciesKey(speciesName);
  const raw = POKEMON_BASE_STATS[key];
  if (!raw) return { ...FALLBACK_STATS };
  return toStatBlock(raw);
}

/** Species key for raw base stats; uses mega form when active in modal context. */
export function getCreatureSpeciesKeyForRawBase(
  creature: Pick<CreatureData, 'name' | 'megaStoneUnlocked' | '_megaStatsSourceName'>,
  options?: { preferMegaForm?: boolean },
): string {
  if (options?.preferMegaForm !== false && creature.megaStoneUnlocked && creature._megaStatsSourceName) {
    return creature._megaStatsSourceName;
  }
  return resolveRosterSpeciesKey(creature.name);
}

export function getCreatureRawBaseStats(
  creature: Pick<CreatureData, 'name' | 'megaStoneUnlocked' | '_megaStatsSourceName'>,
  options?: { preferMegaForm?: boolean },
): SpeciesRawStatBlock {
  const key = getCreatureSpeciesKeyForRawBase(creature, options);
  return getSpeciesRawBaseStats(key);
}

export function sumSpeciesRawBaseStats(block: SpeciesRawStatBlock): number {
  return block.hp + block.attack + block.spattack + block.defense + block.spdefense + block.speed;
}

/** Min/max per stat across the entire dex (cached). Gauge scale uses weighted stats (HP / 2). */
export function computeGlobalSpeciesBaseStatScale(): SpeciesBaseStatScale {
  if (cachedScale) return cachedScale;

  const minima: SpeciesRawStatBlock = {
    hp: Number.POSITIVE_INFINITY,
    attack: Number.POSITIVE_INFINITY,
    spattack: Number.POSITIVE_INFINITY,
    defense: Number.POSITIVE_INFINITY,
    spdefense: Number.POSITIVE_INFINITY,
    speed: Number.POSITIVE_INFINITY,
  };
  const maxima = { ...FALLBACK_STATS };
  let totalMin = Number.POSITIVE_INFINITY;
  let totalMax = 0;

  const names = Object.keys(POKEMON_BASE_STATS);
  for (let i = 0; i < names.length; i++) {
    const name = names[i];
    if (!name) continue;
    const block = getSpeciesRawBaseStats(name);
    const weighted = getWeightedSpeciesRawBaseStats(block);
    const total = sumWeightedSpeciesRawBaseStats(block);
    totalMin = Math.min(totalMin, total);
    totalMax = Math.max(totalMax, total);
    for (const key of STAT_KEYS) {
      minima[key] = Math.min(minima[key], weighted[key]);
      maxima[key] = Math.max(maxima[key], weighted[key]);
    }
  }

  if (!Number.isFinite(totalMin)) totalMin = 0;
  for (const key of STAT_KEYS) {
    if (!Number.isFinite(minima[key])) minima[key] = FALLBACK_STATS[key];
  }

  cachedScale = { minima, maxima, totalMin, totalMax };
  return cachedScale;
}

/** @internal Vitest only */
export function resetGlobalSpeciesBaseStatScaleCacheForTests(): void {
  cachedScale = null;
}

export function pickTooltipBarPercentInRange(value: number, min: number, max: number): number {
  if (!Number.isFinite(value) || !Number.isFinite(min) || !Number.isFinite(max) || max <= min) return 0;
  return Math.max(0, Math.min(100, Math.round(((value - min) / (max - min)) * 100)));
}

export function formatBaseStatBarHtml(value: number, min: number, max: number): string {
  const pct = pickTooltipBarPercentInRange(value, min, max);
  return (
    `<span class="ultimate-slot-pick-tooltip-bar contribution-popover-bar">` +
    `<span class="ultimate-slot-pick-tooltip-bar-fill" style="width: ${pct}%;"></span>` +
    `</span>`
  );
}

export function buildSpeciesBaseStatsTooltipHtml(
  stats: SpeciesRawStatBlock,
  scale: SpeciesBaseStatScale,
  labels: BaseStatTooltipLabels,
): string {
  const rowBorder = '#f1f5f9';
  const rowBorderLast = '#e2e8f0';
  const titleColor = '#94a3b8';
  const headerBorder = '#e2e8f0';
  const bodyColor = '#334155';
  const total = sumWeightedSpeciesRawBaseStats(stats);

  const rowsHtml = labels.rows.map((row, idx) => {
    const value = stats[row.key];
    const barValue = getWeightedSpeciesRawStat(row.key, value);
    const isLast = idx === labels.rows.length - 1;
    return `<tr style="border-bottom: 1px solid ${isLast ? rowBorderLast : rowBorder};">
      <td style="padding: 4px 8px 4px 0;">${row.label}</td>
      <td style="text-align: right;">${value}</td>
      <td class="contribution-popover-bar-cell" style="padding: 4px 0 4px 10px; width: 72px;">${formatBaseStatBarHtml(barValue, scale.minima[row.key], scale.maxima[row.key])}</td>
    </tr>`;
  }).join('');

  return `<div class="base-stats-tooltip-body" style="font-size: 12px; color: ${bodyColor};">
    <table style="width: 100%; border-collapse: collapse;">
      <thead>
        <tr style="border-bottom: 1px solid ${headerBorder};">
          <th style="text-align: left; padding: 4px 8px 4px 0; color: ${titleColor};">${labels.stat}</th>
          <th style="text-align: right; padding: 4px 0; color: ${titleColor};">${labels.value}</th>
          <th style="padding: 4px 0 4px 10px; width: 72px;"></th>
        </tr>
      </thead>
      <tbody>
        ${rowsHtml}
        <tr>
          <td style="padding: 6px 8px 4px 0; font-weight: bold; border-top: 1px solid ${headerBorder};">${labels.total}</td>
          <td style="text-align: right; padding: 6px 0 4px; font-weight: bold; border-top: 1px solid ${headerBorder};">${total}</td>
          <td class="contribution-popover-bar-cell" style="padding: 6px 0 4px 10px; border-top: 1px solid ${headerBorder};">${formatBaseStatBarHtml(total, scale.totalMin, scale.totalMax)}</td>
        </tr>
      </tbody>
    </table>
  </div>`;
}
