export function getFeticheXpToNextLevel(level: number): number {
    const lv = Math.max(1, Math.floor(level));
    return Math.floor(80 * Math.pow(1.12, lv));
}

export function getFeticheMoodKey(index: number): FeticheMoodKey {
    const keys = FETICHE_MOOD_KEYS;
    const i = Math.floor(Number(index) || 0) % keys.length;
    return keys[i < 0 ? i + keys.length : i]!;
}
