/**
 * Per-berry permanent stat effects when feeding the Fétiche.
 */

import {
    BERRY_DEX_KEYS,
    type BerryDexKey,
    type BerryProductionTier,
    getBerryProductionTier,
} from './berryTree.ts';

export type FeticheStatKey = 'hp' | 'attack' | 'spattack' | 'defense' | 'spdefense' | 'speed';

export type FeticheBerryStatEffect = Partial<Record<FeticheStatKey, number>>;

export const FETICHE_STAT_KEYS: readonly FeticheStatKey[] = [
    'hp',
    'attack',
    'spattack',
    'defense',
    'spdefense',
    'speed',
] as const;

const STAT_SHORT: Record<FeticheStatKey, string> = {
    hp: 'HP',
    attack: 'ATK',
    spattack: 'SP.A',
    defense: 'DEF',
    spdefense: 'SP.D',
    speed: 'SPD',
};

function defaultEffectForTier(tier: BerryProductionTier): FeticheBerryStatEffect {
    switch (tier) {
        case 'hp':
            return { hp: 4 };
        case 'status':
        case 'confusion':
            return { hp: 3 };
        case 'pp':
            return { speed: 3 };
        case 'capture':
            return { speed: 1 };
        case 'typeResist':
            return { defense: 2, spdefense: 2 };
        case 'poffin':
            return { attack: 3 };
        case 'special':
            return { spattack: 3, spdefense: 3 };
        case 'ev':
            return { attack: 4, defense: 4 };
        default:
            return { attack: 3 };
    }
}

const BERRY_STAT_OVERRIDES: Partial<Record<BerryDexKey, FeticheBerryStatEffect>> = {
    kelpsy_berry: { attack: 5 },
    qualot_berry: { defense: 5 },
    grepa_berry: { spdefense: 5 },
    hondew_berry: { spattack: 5 },
    tamato_berry: { speed: 5 },
    pomeg_berry: { hp: 5 },
    oran_berry: { hp: 5 },
    sitrus_berry: { hp: 8 },
    liechi_berry: { spattack: 5, spdefense: 5 },
    ganlon_berry: { spattack: 4, spdefense: 4 },
    salac_berry: { spattack: 5, spdefense: 5 },
    petaya_berry: { spattack: 5, spdefense: 5 },
    lansat_berry: { spattack: 5, spdefense: 5 },
    starf_berry: { spattack: 5, spdefense: 5 },
    apicot_berry: { spattack: 4, spdefense: 4 },
    custap_berry: { spattack: 4, spdefense: 4 },
    enigma_berry: { spattack: 4, spdefense: 4 },
    jaboca_berry: { spattack: 4, spdefense: 4 },
    kee_berry: { spattack: 4, spdefense: 4 },
    micle_berry: { spattack: 4, spdefense: 4 },
    roseli_berry: { spattack: 4, spdefense: 4 },
    rowap_berry: { spattack: 4, spdefense: 4 },
    belue_berry: { attack: 4 },
    cornn_berry: { spattack: 4 },
    durin_berry: { spattack: 5 },
    magost_berry: { attack: 4 },
    nomel_berry: { spattack: 4 },
    pamtre_berry: { attack: 4 },
    rabuta_berry: { spattack: 4 },
    spelon_berry: { attack: 4 },
    watmel_berry: { spattack: 4 },
};

function buildBerryStatEffects(): Record<BerryDexKey, FeticheBerryStatEffect> {
    const out = {} as Record<BerryDexKey, FeticheBerryStatEffect>;
    for (const key of BERRY_DEX_KEYS) {
        const override = BERRY_STAT_OVERRIDES[key];
        out[key] = override ? { ...override } : { ...defaultEffectForTier(getBerryProductionTier(key)) };
    }
    return out;
}

export const FETICHE_BERRY_STAT_EFFECTS: Record<BerryDexKey, FeticheBerryStatEffect> =
    Object.freeze(buildBerryStatEffects());

export function getFeticheBerryStatEffect(berryKey: string): FeticheBerryStatEffect {
    const key = berryKey as BerryDexKey;
    if (key in FETICHE_BERRY_STAT_EFFECTS) {
        return FETICHE_BERRY_STAT_EFFECTS[key];
    }
    return defaultEffectForTier(getBerryProductionTier(berryKey));
}

export function scaleFeticheBerryStatEffect(
    base: FeticheBerryStatEffect,
    statEffMult: number,
): FeticheBerryStatEffect {
    const out: FeticheBerryStatEffect = {};
    for (const key of FETICHE_STAT_KEYS) {
        const raw = Number(base[key]) || 0;
        if (raw > 0) {
            out[key] = Math.floor(raw * statEffMult);
        }
    }
    return out;
}

export function hasFeticheBerryStatBase(effect: FeticheBerryStatEffect): boolean {
    return FETICHE_STAT_KEYS.some((key) => (Number(effect[key]) || 0) > 0);
}

export function hasFeticheBerryStatHint(effect: FeticheBerryStatEffect | null | undefined): boolean {
    if (!effect) return false;
    return FETICHE_STAT_KEYS.some((key) => key in effect);
}

export function formatFeticheBerryStatHint(effect: FeticheBerryStatEffect): string {
    const parts: string[] = [];
    for (const key of FETICHE_STAT_KEYS) {
        if (!(key in effect)) continue;
        const value = Number(effect[key]) || 0;
        parts.push(`+${value} ${STAT_SHORT[key]}`);
    }
    return parts.join(', ');
}

export const FETICHE_STAT_HINT_CLASS: Record<FeticheStatKey, string> = {
    hp: 'hp',
    attack: 'attack',
    spattack: 'spattack',
    defense: 'defense',
    spdefense: 'spdefense',
    speed: 'speed',
};

export function formatFeticheBerryStatHintHtml(effect: FeticheBerryStatEffect): string {
    const parts: string[] = [];
    for (const key of FETICHE_STAT_KEYS) {
        if (!(key in effect)) continue;
        const value = Number(effect[key]) || 0;
        const cls = FETICHE_STAT_HINT_CLASS[key];
        const zeroClass = value === 0 ? ' fetiche-stat-hint--zero' : '';
        parts.push(
            `<span class="fetiche-stat-hint fetiche-stat-hint--${cls}${zeroClass}">+${value} ${STAT_SHORT[key]}</span>`,
        );
    }
    return parts.join(', ');
}
